css:
/* Frappe's print stylesheet sets `.print-format td, .print-format th { padding:
   10px !important }`, which no amount of specificity beats. On a grid of eighty
   students by ten assessments that is a sheet eight pages long with a column of
   numbers down the middle of it, so every table rule here is scoped under
   .print-format and marked !important. Proof of Registration carries the same
   note for the same reason.

   The institute green is written out literally rather than as a custom
   property: this site renders PDFs with wkhtmltopdf, whose WebKit predates CSS
   variables, so a var() would look right in the browser preview and come out
   black in the PDF anyone receives. */

/* Anchored left and scaled to 78%, which is what centres the institute text on
   the page without taking the logo off it. The reasoning is written out in
   Proof of Registration, which has the same letterhead problem. */
.print-format .grid-letterhead {
	margin-bottom: 8px;
	text-align: left !important;
}
.print-format .grid-letterhead div {
	text-align: left !important;
}
.print-format .grid-letterhead img {
	width: 78%;
	max-width: 78%;
	height: auto;
}

.print-format .mark-sheet-grid {
	font-size: 9pt;
	line-height: 1.35;
	color: #000;
}

.print-format .grid-title {
	text-align: center;
	font-size: 14pt;
	font-weight: bold;
	color: #1a7a3c;
	margin: 0 0 12px;
}

/* Fixed label and colon columns so the colons line up down each half, rather
   than each row ending wherever its label happens to. */
.print-format .grid-identity {
	border: none;
	border-collapse: collapse;
	width: 100%;
	/* Fixed, so the cells of a row that has nothing on its left still hold their
	   columns. With an auto layout the blank Student Group cells collapsed and
	   dragged Printed back under the left-hand half. */
	table-layout: fixed;
	margin: 0 0 14px;
}
.print-format .grid-identity td {
	border: none !important;
	padding: 0 0 2px 0 !important;
	vertical-align: baseline !important;
	white-space: nowrap;
}
.print-format .grid-identity td.label {
	width: 92px;
	font-weight: bold;
}
.print-format .grid-identity td.colon {
	width: 12px;
}
.print-format .grid-identity td.value {
	width: 246px;
	padding-right: 16px !important;
}

/* The grid itself. Fixed layout, because a mark has to sit in the same place on
   every row for a column of them to be readable, and a long module name would
   otherwise take the width the numbers need. */
.print-format .grid-marks {
	width: 100%;
	table-layout: fixed;
	border-collapse: collapse;
	margin: 0 0 8px;
	font-size: 8pt;
}
.print-format .grid-marks th,
.print-format .grid-marks td {
	border: 0.5pt solid #999 !important;
	padding: 2px 3px !important;
	vertical-align: middle !important;
}
/* Repeated at the top of every page: a grid whose header is on page one is a
   page of anonymous numbers from page two on. */
.print-format .grid-marks thead {
	display: table-header-group;
}
.print-format .grid-marks tr {
	page-break-inside: avoid;
}
/* Twelve columns is far enough across for the eye to change rows on the way.
   A cell that sets its own background paints over this, which is what keeps the
   totals and the off-sheet cells readable on a shaded row. */
.print-format .grid-marks tbody tr:nth-child(even) {
	background-color: #f6f8f6;
}
.print-format .grid-marks thead th {
	background-color: #eef4ef;
	font-size: 6pt;
	/* Narrower than the body cells: the few pixels the side padding costs are
	   what decides whether a label as long as 'Assignment 1' wraps at its space
	   or through the middle of the word. */
	padding: 2px 1px !important;
	line-height: 1.15;
	font-weight: bold;
	text-align: center;
	vertical-align: bottom !important;
	/* `word-wrap` rather than `word-break`: a narrow column has to wrap
	   "Assignment 1" somewhere, and it should be at the space. break-word broke
	   mid-word and printed "Assign/ment 1" and "Theor/y Exam"; this only breaks a
	   word that will not fit on a line of its own. The legacy spelling is the one
	   this site's wkhtmltopdf WebKit understands. */
	word-wrap: break-word;
}
.print-format .grid-marks thead th.col-student,
.print-format .grid-marks thead th.col-name {
	text-align: left;
	font-size: 7.5pt;
}
.print-format .grid-marks .out-of {
	display: block;
	font-weight: normal;
	color: #555;
}

/* Proportions rather than pixel widths, and no width at all on the mark
   columns: with a fixed layout the unsized columns divide what is left equally,
   so adding an assessment narrows the marks instead of pushing the table off
   the page. Pixel widths fitted the eight-assessment scheme this was built
   against and overflowed a wider one. */
.print-format .grid-marks .col-student {
	width: 9%;
	font-size: 7pt;
	white-space: nowrap;
}
/* Wrapped rather than truncated. A mark sheet is how a person is identified
   against their marks, and an ellipsis through a surname is the one thing on it
   that must not be shortened -- a second line costs nothing by comparison. */
.print-format .grid-marks .col-name {
	width: 24%;
	white-space: normal;
	word-wrap: break-word;
}
.print-format .grid-marks .col-mark {
	text-align: center;
}
.print-format .grid-marks .col-total {
	width: 6%;
	text-align: center;
	font-weight: bold;
	background-color: #f7f7f7;
}
/* A cell the sheet has no row for at all, which is not the same as a cell with
   no mark in it yet. A re-sitting carries only the papers being sat again, so
   the two have to look different -- and an empty box is somewhere to write. */
.print-format .grid-marks .off-sheet {
	background-color: #e4e4e4;
}
.print-format .grid-marks .no-mark {
	color: #777;
}

.print-format .grid-legend,
.print-format .grid-summary,
.print-format .grid-note,
.print-format .grid-empty {
	font-size: 8pt;
	margin: 0 0 6px;
}
.print-format .grid-legend {
	color: #555;
}
.print-format .grid-note {
	border-left: 2pt solid #1a7a3c;
	padding-left: 6px;
	page-break-inside: avoid;
}
.print-format .grid-warning {
	border-left-color: #b00020;
}
.print-format .grid-empty {
	font-style: italic;
	color: #555;
}

.print-format .grid-signoff {
	width: 100%;
	border: none;
	border-collapse: collapse;
	margin-top: 34px;
	page-break-inside: avoid;
}
.print-format .grid-signoff td {
	border: none !important;
	padding: 0 18px 0 0 !important;
	width: 33%;
	vertical-align: top !important;
}
.print-format .grid-signoff .signature-rule {
	border-top: 1px solid #000;
}
.print-format .grid-signoff .signature-role {
	font-weight: bold;
	color: #1a7a3c;
	font-size: 8pt;
	padding-top: 2px;
}
.print-format .grid-signoff .signature-name {
	font-size: 8pt;
}
